import z3

A = list(range(12))
B = list(range(12, 25))
nA = len(A)
nB = len(B)

e = [[z3.Bool(f'e_{i}_{j}') for j in range(nB)] for i in range(nA)]

s = z3.Solver()

for i in range(nA):
    deg = z3.Sum([z3.If(e[i][k], 1, 0) for k in range(nB)])
    s.add(deg >= 5, deg <= 6)

for j in range(nB):
    deg = z3.Sum([z3.If(e[k][j], 1, 0) for k in range(nA)])
    s.add(deg >= 5, deg <= 6)

for i1 in range(nA):
    for i2 in range(i1+1, nA):
        common = z3.Sum([z3.If(z3.And(e[i1][k], e[i2][k]), 1, 0) for k in range(nB)])
        s.add(common <= 1)

for j1 in range(nB):
    for j2 in range(j1+1, nB):
        common = z3.Sum([z3.If(z3.And(e[k][j1], e[k][j2]), 1, 0) for k in range(nA)])
        s.add(common <= 1)

s.set('timeout', 10000)
result = s.check()
print(result)
if result == z3.sat:
    m = s.model()
    edges = []
    for i in range(nA):
        for j in range(nB):
            if m[e[i][j]]:
                edges.append((A[i], B[j]))
    print(sorted(edges))
    print(len(edges))
else:
    print("UNSATISFIABLE")

